/**
 * Slug preview used by both the create form and `createProject`, so what the
 * user sees while typing is what the row ends up with.
 */
export async function suggestProjectSlug(
  orgId: OrgId,
  name: string,
): Promise<string> {
  const taken = await projectRepo.listTakenProjectSlugs(orgId);
  return uniqueSlug(name, taken);
}

async function listAllLiveIssues(
  orgId: OrgId,
  projectId: ProjectId,
) {
  const issues = [] as Awaited<ReturnType<typeof issueRepo.listIssues>>["items"][number][];
  let cursor: string | null = null;
  do {
    const page = await issueRepo.listIssues({
      orgId,
      projectId,
      limit: 100,
      cursor,
    });
    issues.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);
  return issues;
}
